package pag.domains.gen;

import org.junit.jupiter.api.Test;
import pag.api.*;

import java.math.BigInteger;
import java.util.*;

import static org.junit.jupiter.api.Assertions.*;

class SignDomainTest {

    private final SignDomain domain = new SignDomain();

    @Test
    void testTopIsNotBottom() {
        assertFalse(domain.isBottom(domain.top()));
    }

    @Test
    void testBottomIsBottom() {
        assertTrue(domain.isBottom(domain.bottom()));
    }

    @Test
    void testEntailsBottom() {
        Map<String, SignDomain.Sign> bottom = domain.bottom();
        Map<String, SignDomain.Sign> top = domain.top();

        assertTrue(domain.entails(bottom, top));
        assertFalse(domain.entails(top, bottom));
    }

    @Test
    void testJoin() {
        Map<String, SignDomain.Sign> state1 = new HashMap<>();
        state1.put("x", SignDomain.Sign.POSITIVE);

        Map<String, SignDomain.Sign> state2 = new HashMap<>();
        state2.put("x", SignDomain.Sign.NEGATIVE);

        Map<String, SignDomain.Sign> joined = domain.join(state1, state2);

        // POSITIVE + NEGATIVE = UNKNOWN
        assertEquals(SignDomain.Sign.UNKNOWN, joined.get("x"));
    }

    @Test
    void testJoinSameSign() {
        Map<String, SignDomain.Sign> state1 = new HashMap<>();
        state1.put("x", SignDomain.Sign.POSITIVE);

        Map<String, SignDomain.Sign> state2 = new HashMap<>();
        state2.put("x", SignDomain.Sign.POSITIVE);

        Map<String, SignDomain.Sign> joined = domain.join(state1, state2);

        assertEquals(SignDomain.Sign.POSITIVE, joined.get("x"));
    }

    @Test
    void testAssignTransfer() {
        Map<String, SignDomain.Sign> post = new HashMap<>();
        post.put("x", SignDomain.Sign.POSITIVE);

        LVal.Local target = new LVal.Local("x", "int");
        RVal source = new RVal.IntConst(BigInteger.valueOf(5));
        Step.Assign assign = new Step.Assign(target, source);

        Map<String, SignDomain.Sign> pre = domain.transfer(assign, post);

        // After assignment, x is unconstrained before
        assertNull(pre.get("x"));
    }

    @Test
    void testAssignWithVariableSource() {
        Map<String, SignDomain.Sign> post = new HashMap<>();
        post.put("x", SignDomain.Sign.ZERO);

        LVal.Local target = new LVal.Local("x", "int");
        LVal.Local source = new LVal.Local("y", "int");
        Step.Assign assign = new Step.Assign(target, source);

        Map<String, SignDomain.Sign> pre = domain.transfer(assign, post);

        // x is unconstrained, y must be ZERO
        assertNull(pre.get("x"));
        assertEquals(SignDomain.Sign.ZERO, pre.get("y"));
    }

    @Test
    void testAssumeTransfer() {
        Map<String, SignDomain.Sign> post = new HashMap<>();
        post.put("x", SignDomain.Sign.POSITIVE);

        RVal cond = new RVal.Binop(
            new LVal.Local("x", "int"),
            BinOp.Gt,
            new RVal.IntConst(BigInteger.ZERO)
        );
        Step.Assume assume = new Step.Assume(cond);

        Map<String, SignDomain.Sign> pre = domain.transfer(assume, post);

        // x should still be POSITIVE (already satisfies x > 0)
        assertEquals(SignDomain.Sign.POSITIVE, pre.get("x"));
    }

    @Test
    void testCallTransfer() {
        Map<String, SignDomain.Sign> post = new HashMap<>();
        post.put("x", SignDomain.Sign.POSITIVE);

        LVal.Local target = new LVal.Local("x", "int");
        MethodId callee = new MethodId("pag.probe.Rand", "randInt", List.of(), "int");
        Step.Call call = new Step.Call(Optional.of(target), callee, List.of());

        Map<String, SignDomain.Sign> pre = domain.transfer(call, post);

        // x is unconstrained before randInt()
        assertNull(pre.get("x"));
    }

    @Test
    void testSignAddition() {
        // POSITIVE + POSITIVE = POSITIVE
        Map<String, SignDomain.Sign> state = new HashMap<>();
        state.put("x", SignDomain.Sign.POSITIVE);
        state.put("y", SignDomain.Sign.POSITIVE);

        RVal expr = new RVal.Binop(
            new LVal.Local("x", "int"),
            BinOp.Add,
            new LVal.Local("y", "int")
        );

        assertEquals(SignDomain.Sign.POSITIVE, 
            ((SignDomain) domain).evaluateSign(state, expr));
    }

    @Test
    void testSignMultiplication() {
        // POSITIVE * NEGATIVE = NEGATIVE
        Map<String, SignDomain.Sign> state = new HashMap<>();
        state.put("x", SignDomain.Sign.POSITIVE);
        state.put("y", SignDomain.Sign.NEGATIVE);

        RVal expr = new RVal.Binop(
            new LVal.Local("x", "int"),
            BinOp.Mult,
            new LVal.Local("y", "int")
        );

        assertEquals(SignDomain.Sign.NEGATIVE, 
            ((SignDomain) domain).evaluateSign(state, expr));
    }

    @Test
    void testConstrainToZero() {
        Map<String, SignDomain.Sign> state = new HashMap<>();
        state.put("x", SignDomain.Sign.POSITIVE);

        RVal expr = new RVal.Binop(
            new LVal.Local("x", "int"),
            BinOp.Eq,
            new RVal.IntConst(BigInteger.ZERO)
        );

        // Applying x == 0 constraint
        Map<String, SignDomain.Sign> constrained = 
            ((SignDomain) domain).applyConstraint(state, expr);

        // x should now be ZERO
        assertEquals(SignDomain.Sign.ZERO, constrained.get("x"));
    }

    @Test
    void testWiden() {
        Map<String, SignDomain.Sign> state1 = new HashMap<>();
        state1.put("x", SignDomain.Sign.POSITIVE);

        Map<String, SignDomain.Sign> state2 = new HashMap<>();
        state2.put("x", SignDomain.Sign.NEGATIVE);

        Map<String, SignDomain.Sign> widened = domain.widen(state1, state2);

        // For this domain, widen = join
        assertEquals(SignDomain.Sign.UNKNOWN, widened.get("x"));
    }

    @Test
    void testEntailsWithDifferentVars() {
        Map<String, SignDomain.Sign> state1 = new HashMap<>();
        state1.put("x", SignDomain.Sign.POSITIVE);

        Map<String, SignDomain.Sign> state2 = new HashMap<>();
        state2.put("y", SignDomain.Sign.POSITIVE);

        // state1 does not entail state2 (different variables)
        assertFalse(domain.entails(state1, state2));
    }

    @Test
    void testEntailsSubset() {
        Map<String, SignDomain.Sign> state1 = new HashMap<>();
        state1.put("x", SignDomain.Sign.ZERO);

        Map<String, SignDomain.Sign> state2 = new HashMap<>();
        state2.put("x", SignDomain.Sign.NONNEGATIVE);

        // ZERO entails NONNEGATIVE
        assertTrue(domain.entails(state1, state2));
    }

    @Test
    void testComplexAssignment() {
        Map<String, SignDomain.Sign> post = new HashMap<>();
        post.put("result", SignDomain.Sign.ZERO);

        LVal.Local target = new LVal.Local("result", "int");
        RVal source = new RVal.Binop(
            new LVal.Local("x", "int"),
            BinOp.Eq,
            new LVal.Local("y", "int")
        );
        Step.Assign assign = new Step.Assign(target, source);

        Map<String, SignDomain.Sign> pre = domain.transfer(assign, post);

        // result is unconstrained before assignment
        assertNull(pre.get("result"));
    }

    @Test
    void testBottomPropagation() {
        Map<String, SignDomain.Sign> bottom = domain.bottom();

        LVal.Local target = new LVal.Local("x", "int");
        RVal source = new RVal.IntConst(BigInteger.valueOf(5));
        Step.Assign assign = new Step.Assign(target, source);

        Map<String, SignDomain.Sign> result = domain.transfer(assign, bottom);

        // Bottom propagates through transfer
        assertTrue(domain.isBottom(result));
    }
}
